const c5=canary.filter(r=>r.status>=500), s5=stable.filter(r=>r.status>=500);
print('canary 5xx total', c5.length, 'stable 5xx total', s5.length);
const byPath={}; c5.forEach(r=>byPath[r.path]=(byPath[r.path]||0)+1);
print('canary 5xx by path', JSON.stringify(byPath));
print('canary 5xx timestamps', JSON.stringify(c5.map(r=>Math.round(r.t))));
const cco=canary.filter(r=>r.path==='/checkout'), sco=stable.filter(r=>r.path==='/checkout');
print('canary /checkout n', cco.length, '5xx', cco.filter(r=>r.status>=500).length, 'err%', (100*cco.filter(r=>r.status>=500).length/cco.length).toFixed(2));
print('stable /checkout n', sco.length, '5xx', sco.filter(r=>r.status>=500).length);
print('canary p95', pct(canary.map(r=>r.ms),95), 'stable p95', pct(stable.map(r=>r.ms),95));
const statuses={}; canary.forEach(r=>statuses[r.status]=(statuses[r.status]||0)+1);
print('canary status codes', JSON.stringify(statuses));

const ms=a=>a.map(r=>r.ms);
print('try p=95 ->','canary',pct(ms(canary),95),'stable',pct(ms(stable),95));
print('try p=0.95 ->','canary',pct(ms(canary),0.95),'stable',pct(ms(stable),0.95));
const ck=p=>canary.filter(r=>r.path==='/checkout');
const cck=canary.filter(r=>r.path==='/checkout'), sck=stable.filter(r=>r.path==='/checkout');
print('checkout p50/p95 canary',pct(ms(cck),50),pct(ms(cck),95),'stable',pct(ms(sck),50),pct(ms(sck),95));
for(let w=0;w<120;w+=30){
  const cw=canary.filter(r=>r.t>=w&&r.t<w+30), sw=stable.filter(r=>r.t>=w&&r.t<w+30);
  print('window',w+'-'+(w+30)+'s','canary5xx',cw.filter(r=>r.status>=500).length,'stable5xx',sw.filter(r=>r.status>=500).length,'canary_n',cw.length);
}
print('canary 5xx count in each half:','first60',canary.filter(r=>r.status>=500&&r.t<60).length,'last60',canary.filter(r=>r.status>=500&&r.t>=60).length);

