{
  "decision": "ROLLBACK",
  "why": "The canary served 10 5xx responses while the 3 stable pods served 0 (claim 1). All 10 canary failures are on /checkout - 10 of 483 canary checkout requests = 2.07% - with zero 5xx on any other canary path, while stable served 1455 checkout requests with 0 5xx (claim 2). The failures appear in every 30s window of the test, 1/3/3/3 (claim 3). Latency is not the differentiator: overall p95 is 96ms on canary vs 94ms on stable (claim 4). Judgement: a failure mode that is confined to the revenue-critical checkout path, runs for the whole 120s instead of only during warm-up, and has an exactly-zero baseline on 1455 stable checkout requests is a genuine regression in 1.1, not sampling noise or cold-start noise. At 100% traffic this would mean roughly 1 in 50 checkouts failing for every customer, which is worse than delaying the release, so roll back and let the owners reproduce the checkout 500s before re-trying the canary.",
  "claims": [
    {
      "claim": "The canary (1.1) returned 10 5xx responses during the test; the stable pods (1.0) returned 0.",
      "query": "print('canary5xx', canary.filter(r=>r.status>=500).length, 'stable5xx', stable.filter(r=>r.status>=500).length);",
      "expect": "canary5xx 10 stable5xx 0"
    },
    {
      "claim": "All 10 canary 5xx are on /checkout (10 of 483 canary checkout requests = 2.07%), no other canary path had a 5xx, and stable served 1455 checkout requests with 0 5xx.",
      "query": "const cc=canary.filter(r=>r.path==='/checkout'), ce=cc.filter(r=>r.status>=500), other=canary.filter(r=>r.status>=500&&r.path!=='/checkout').length, sc=stable.filter(r=>r.path==='/checkout'), se=sc.filter(r=>r.status>=500).length; print('checkout_5xx', ce.length, 'checkout_n', cc.length, 'errpct', (100*ce.length/cc.length).toFixed(2), 'non_checkout_5xx', other, 'stable_checkout_5xx', se, 'stable_checkout_n', sc.length);",
      "expect": "checkout_5xx 10 checkout_n 483 errpct 2.07 non_checkout_5xx 0 stable_checkout_5xx 0 stable_checkout_n 1455"
    },
    {
      "claim": "The canary 5xx are spread across the whole test, with 1, 3, 3 and 3 errors in the four consecutive 30s windows.",
      "query": "const w=[0,1,2,3].map(i=>canary.filter(r=>r.status>=500&&r.t>=i*30&&r.t<(i+1)*30).length); print('canary 5xx per 30s window', w.join(' '));",
      "expect": "canary 5xx per 30s window 1 3 3 3"
    },
    {
      "claim": "Overall latency is comparable: canary p95 is 96ms and stable p95 is 94ms.",
      "query": "print('p95 canary', pct(canary.map(r=>r.ms),0.95), 'stable', pct(stable.map(r=>r.ms),0.95));",
      "expect": "p95 canary 96 stable 94"
    }
  ]
}

