print('CLAIM2 canary5xx_by_path=' + JSON.stringify(paths));
const cco=canary.filter(r=>r.path==='/checkout'), sco=stable.filter(r=>r.path==='/checkout');
print('CLAIM3 checkout canary n=' + cco.length + ' 5xx=' + cco.filter(is5).length + ' err%=' + (100*cco.filter(is5).length/cco.length).toFixed(2) + ' | stable n=' + sco.length + ' 5xx=' + sco.filter(is5).length);
const ms=a=>a.map(r=>r.ms);
print('CLAIM4 p95 canary=' + pct(ms(canary),0.95) + ' stable=' + pct(ms(stable),0.95) + ' p99 canary=' + pct(ms(canary),0.99) + ' stable=' + pct(ms(stable),0.99));
let w=[];
for(let i=0;i<4;i++){const a=i*30,b=a+30;const cw=canary.filter(r=>r.t>=a&&r.t<b);w.push((a+'-'+b+'s:'+cw.filter(is5).length));}
print('CLAIM5 canary5xx_per_window ' + w.join(' '));
print('CLAIM6 first_canary_5xx_t=' + c5[0].t + ' last_canary_5xx_t=' + c5[c5.length-1].t);

